SELECT store_id, last_restock_month, max_quantity FROM (SELECT store_id, DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_month, MAX(quantity) AS max_quantity FROM inventory GROUP BY store_id, DATE_FORMAT(last_restock, 'yyyy-MM')) AS sub WHERE max_quantity >= 140 ORDER BY max_quantity, store_id, last_restock_month LIMIT 1
